import AVFoundation
import SwiftUI

/// Music and sound effects. Every sound is original, generated by `tools/audio/make_audio.py`.
/// The session is "ambient": it follows the silent switch and mixes with the player's own music.
@MainActor
final class GameAudio {
    static let shared = GameAudio()
    static let musicKey = "audio.music"
    static let effectsKey = "audio.effects"

    enum Music: String { case theme, crowd }
    enum Effect: String, CaseIterable { case bat, four, six, wicket, win }

    /// Volumes: the theme sits under the UI; the crowd is the match-day bed.
    static let themeVolume: Float = 0.45
    static let crowdVolume: Float = 0.5

    private var music: AVAudioPlayer?
    private var current: Music?
    private var effects: [Effect: [AVAudioPlayer]] = [:]
    private var configured = false

    var musicOn: Bool { UserDefaults.standard.object(forKey: Self.musicKey) as? Bool ?? true }
    var effectsOn: Bool { UserDefaults.standard.object(forKey: Self.effectsKey) as? Bool ?? true }

    private func configure() {
        guard !configured else { return }
        configured = true
        let session = AVAudioSession.sharedInstance()
        try? session.setCategory(.ambient, mode: .default, options: [.mixWithOthers])
        try? session.setActive(true)
    }

    private func player(_ name: String) -> AVAudioPlayer? {
        guard let url = Bundle.main.url(forResource: name, withExtension: "m4a") else { return nil }
        return try? AVAudioPlayer(contentsOf: url)
    }

    /// Crossfades to a music loop (no-op if it's already playing).
    func play(_ m: Music) {
        configure()
        guard musicOn else { stopMusic(); return }
        let volume = m == .theme ? Self.themeVolume : Self.crowdVolume
        if current == m, let p = music {
            if !p.isPlaying { p.play() }
            p.setVolume(volume, fadeDuration: 0.6)
            return
        }
        fadeOut(music)
        guard let p = player(m.rawValue) else { return }
        p.numberOfLoops = -1
        p.volume = 0
        p.prepareToPlay()
        p.play()
        p.setVolume(volume, fadeDuration: 1.2)
        music = p
        current = m
    }

    func stopMusic() {
        fadeOut(music)
        music = nil
        current = nil
    }

    private func fadeOut(_ p: AVAudioPlayer?) {
        guard let p else { return }
        p.setVolume(0, fadeDuration: 0.8)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.9) { p.stop() }
    }

    /// Back from the background: iOS paused the player.
    func resume() {
        guard musicOn, let p = music, !p.isPlaying else { return }
        p.play()
    }

    func effect(_ e: Effect, volume: Float = 0.9) {
        configure()
        guard effectsOn else { return }
        if effects[e] == nil {
            effects[e] = (0..<2).compactMap { _ in player(e.rawValue) }
            effects[e]?.forEach { $0.prepareToPlay() }
        }
        guard let pool = effects[e], let p = pool.first(where: { !$0.isPlaying }) ?? pool.first else { return }
        p.currentTime = 0
        p.volume = volume
        p.play()
    }

    /// A settings switch changed.
    func refresh(fallback: Music = .theme) {
        if !musicOn { stopMusic() } else if current == nil { play(fallback) }
    }

    /// The sound for one delivery in the live view.
    func ball(_ label: String) {
        switch label {
        case "W": effect(.wicket)
        case "6": effect(.six)
        case "4": effect(.four)
        case "1", "2", "3": effect(.bat, volume: 0.45)
        default: break
        }
    }
}

/// Music and sound-effect switches (menus and Settings).
struct SoundToggles: View {
    @AppStorage(GameAudio.musicKey) private var music = true
    @AppStorage(GameAudio.effectsKey) private var effects = true

    var body: some View {
        Toggle(isOn: $music) { Label("Music", systemImage: "music.note") }
            .onChange(of: music) { _ in GameAudio.shared.refresh() }
        Toggle(isOn: $effects) { Label("Sound effects", systemImage: "speaker.wave.2") }
    }
}
